//! Rule-4 queue-position golden of the simulated venue (v1.17 B9, review
//! row X-10): `tests/golden/expected_venue_queue.json`, generated by
//! `python/tools/make_golden_venue_queue.py` from the Python execution
//! simulator (the rule-4 reference) with zero latency. Every fill (order,
//! event time, quantity, price, liquidity) and every order's final queue
//! state must match exactly.

use marketdata::MarketEvent;
use venue::{ExecStatus, OrderRequest, SimVenueConfig, SimulatedVenue};

fn repo_path(rel: &str) -> std::path::PathBuf {
    std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..").join(rel)
}

fn load_golden() -> serde_json::Value {
    let text = std::fs::read_to_string(repo_path("tests/golden/expected_venue_queue.json")).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn event(v: &serde_json::Value) -> MarketEvent {
    MarketEvent {
        event_id: v["event_id"].as_u64().unwrap(),
        instrument_id: v["instrument_id"].as_u64().unwrap() as u32,
        venue_id: v["venue_id"].as_u64().unwrap() as u16,
        exchange_ts: v["exchange_ts"].as_i64().unwrap(),
        receive_ts: v["receive_ts"].as_i64().unwrap(),
        sequence: v["sequence"].as_u64().unwrap(),
        event_type: v["event_type"].as_u64().unwrap() as u8,
        side: v["side"].as_u64().unwrap() as u8,
        price_ticks: v["price_ticks"].as_i64().unwrap(),
        qty: v["qty"].as_i64().unwrap(),
        order_id: v["order_id"].as_u64().unwrap(),
        trade_id: v["trade_id"].as_u64().unwrap(),
    }
}

/// `(order_id, ts, qty, price_ticks, liquidity)` of one fill.
type FillRow = (u64, i64, i64, i64, &'static str);

fn fill_rows(reports: &[venue::ExecutionReport], liquidity: &'static str) -> Vec<FillRow> {
    reports
        .iter()
        .filter(|r| r.filled_qty > 0)
        .map(|r| (r.order_id, r.exchange_ts, r.filled_qty, r.fill_price_ticks, liquidity))
        .collect()
}

fn expected_fills(v: &serde_json::Value) -> Vec<FillRow> {
    v["expected_fills"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| {
            (
                f["order_id"].as_u64().unwrap(),
                f["ts"].as_i64().unwrap(),
                f["qty"].as_i64().unwrap(),
                f["price_ticks"].as_i64().unwrap(),
                if f["liquidity"] == "maker" { "maker" } else { "taker" },
            )
        })
        .collect()
}

/// Replay one vector; returns the fills in emission order.
fn replay(golden: &serde_json::Value, vec: &serde_json::Value) -> (Vec<FillRow>, SimulatedVenue) {
    let cfg = SimVenueConfig {
        venue_id: golden["venue_id"].as_u64().unwrap() as u16,
        latency_ns: 0,
        taker_fee_per_share: golden["taker_fee_per_share"].as_f64().unwrap(),
        maker_rebate_per_share: golden["maker_rebate_per_share"].as_f64().unwrap(),
    };
    let instrument_id = golden["instrument_id"].as_u64().unwrap() as u32;
    let mut venue = SimulatedVenue::new(cfg).unwrap();
    let mut fills = Vec::new();
    let actions = vec["actions"].as_array().unwrap();
    for ev in vec["events"].as_array().unwrap() {
        let reports = venue.on_market_event(&event(ev)).unwrap();
        fills.extend(fill_rows(&reports, "maker"));
        let after = ev["event_id"].as_u64();
        for action in actions.iter().filter(|a| a["after_event"].as_u64() == after) {
            if let Some(s) = action.get("submit") {
                let order = OrderRequest {
                    order_id: s["order_id"].as_u64().unwrap(),
                    instrument_id,
                    side: s["side"].as_u64().unwrap() as u8,
                    qty: s["qty"].as_i64().unwrap(),
                    price_ticks: s["price_ticks"].as_i64().unwrap(),
                    order_type: s["order_type"].as_u64().unwrap() as u8,
                    venue_id: cfg.venue_id,
                    strategy_id: "S1".to_string(),
                    urgency: 0.0,
                    timestamp: s["decision_ts"].as_i64().unwrap(),
                };
                let reports = venue.submit(&order).unwrap();
                assert_eq!(reports[0].status, ExecStatus::New.as_u8(), "{}: submit accepted", vec["name"]);
                fills.extend(fill_rows(&reports, "taker"));
            } else {
                let id = action["cancel"].as_u64().unwrap();
                let rep = venue.cancel(id, ev["exchange_ts"].as_i64().unwrap());
                assert_eq!(rep.status, ExecStatus::Canceled.as_u8(), "{}: cancel {id}", vec["name"]);
            }
        }
    }
    (fills, venue)
}

#[test]
fn golden_venue_queue_fills_and_final_state_match() {
    let golden = load_golden();
    assert_eq!(golden["x-version"].as_u64(), Some(1));
    let vectors = golden["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 5, "golden must pin at least five vectors");
    for vec in vectors {
        let name = vec["name"].as_str().unwrap();
        let (fills, venue) = replay(&golden, vec);
        assert_eq!(fills, expected_fills(vec), "{name}: fills");
        for row in vec["expected_final"].as_array().unwrap() {
            let id = row["order_id"].as_u64().unwrap();
            let pos = venue.queue_position(id);
            assert_eq!(pos.is_some(), row["resting"].as_bool().unwrap(), "{name}: order {id} resting");
            if let Some(pos) = pos {
                assert_eq!(pos.remaining, row["remaining"].as_i64().unwrap(), "{name}: order {id} remaining");
                assert_eq!(pos.ahead_qty, row["ahead_qty"].as_i64().unwrap(), "{name}: order {id} ahead_qty");
            } else {
                // not resting: filled or cancelled; the remaining is what the
                // fills left (the golden records it from the reference)
                let qty: i64 = vec["actions"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter_map(|a| a.get("submit"))
                    .find(|s| s["order_id"].as_u64() == Some(id))
                    .map(|s| s["qty"].as_i64().unwrap())
                    .unwrap();
                let filled: i64 = fills.iter().filter(|f| f.0 == id).map(|f| f.2).sum();
                assert_eq!(qty - filled, row["remaining"].as_i64().unwrap(), "{name}: order {id} remaining");
            }
        }
    }
}

#[test]
fn golden_venue_queue_replay_is_deterministic() {
    let golden = load_golden();
    for vec in golden["vectors"].as_array().unwrap() {
        let (a, _) = replay(&golden, vec);
        let (b, _) = replay(&golden, vec);
        assert_eq!(a, b);
    }
}
